class Solution:
    def mergeLines(self, first: Optional[ListNode], second: Optional[ListNode]) -> Optional[ListNode]:
        vals = []
        for node in (first, second):
            while node:
                vals.append(node.val)
                node = node.next
        vals.sort()
        dummy = tail = ListNode()
        for v in vals:
            tail.next = ListNode(v)
            tail = tail.next
        return dummy.next

