static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

struct ListNode* mergeLines(struct ListNode* first, struct ListNode* second) {
    int n = 0;
    for (struct ListNode* p = first; p; p = p->next) n++;
    for (struct ListNode* p = second; p; p = p->next) n++;
    int* vals = malloc((n + 1) * sizeof(int));
    int k = 0;
    for (struct ListNode* p = first; p; p = p->next) vals[k++] = p->val;
    for (struct ListNode* p = second; p; p = p->next) vals[k++] = p->val;
    qsort(vals, n, sizeof(int), cmp_int);
    struct ListNode dummy = {0, NULL}, *tail = &dummy;
    for (int i = 0; i < n; i++) {
        tail->next = malloc(sizeof(struct ListNode));
        tail = tail->next;
        tail->val = vals[i];
        tail->next = NULL;
    }
    free(vals);
    return dummy.next;
}

